/* rv32emu probe: instructions retired by one rubik_solve call for each state
 * given in probe_states.h (generated by run.sh), measured like PERF_CALL in
 * tests/tperf.h: two counter reads around the call, minus the cost of an
 * empty pair of reads. Linked with build/rubik/<O>/impl.o, the object the
 * harness builds, so the code under test is the graded one.
 *
 * Build and run: bash mytests/rubik/target/run.sh <output-dir>
 */
#include <stddef.h>
#include <stdint.h>
#include "print.h"

int rubik_solve(const char *state, char *out, size_t cap);
extern uint64_t get_instret(void);

#include "probe_states.h"

int main(void)
{
    static char out[96];
    for (unsigned i = 0; i < sizeof states / sizeof states[0]; ++i) {
        uint64_t a = get_instret();
        uint64_t b = get_instret();
        uint64_t t0 = get_instret();
        int n = rubik_solve(states[i], out, sizeof out);
        uint64_t t1 = get_instret();
        uint64_t used = (t1 - t0) - (b - a);
        bm_printf("@@probe state=%s n=%d instret=%llu out=%s\n", states[i], n,
                  (unsigned long long) used, n >= 0 ? out : "");
    }
    return 0;
}
